pub fn child_inferred_or_empty(ch: Rc<Node>) -> Rc<Node> {
    if (ch.inferred.clone() != None) {
        match (*rt_node(ch.clone())).clone() {
    NodeType::Typed { node: rt, .. } => rt.clone(),
    NodeType::InferError { .. } => leaf_type_node("Unit".to_string(), ch.span.clone()),
    NodeType::Untyped => leaf_type_node("Unit".to_string(), ch.span.clone()),
}
} else {
        leaf_type_node("".to_string(), ch.span.clone())
}
}

pub fn node_inferred_to_outputs(rt: Rc<Node>) -> Vec<Rc<Field>> {
    if is_conj_with_children(rt.clone()) {
        { let mut __result = Vec::new(); for ch in rt.children.clone().iter().cloned() { __result.push(Rc::new(Field {
    name: ch.name.clone(),
    type_expr: child_inferred_or_empty(ch.clone()),
    cardinality: Cardinality::Required,
    default_value: ch.body.clone(),
    from_key: None,
    span: ch.span.clone(),
})); } __result }
} else {
        vec![Rc::new(Field {
    name: "value".to_string(),
    type_expr: rt.clone(),
    cardinality: Cardinality::Required,
    default_value: None,
    from_key: None,
    span: rt.span.clone(),
})]
}
}

