pub fn parse_item(tokens: Rc<Vec<Rc<Token>>>, state: Rc<ParserState>) -> Rc<ItemResult> {
    {
        let s = skip_newlines(tokens.clone(), state.clone());
let sh = peek_shape(tokens.clone(), s.clone());
match sh.clone() {
    Some(TokenShape::ShKwType) => parse_type_def(tokens.clone(), s.clone()),
    Some(TokenShape::ShKwFn) => parse_fn_def(tokens.clone(), s.clone()),
    Some(TokenShape::ShKwFunc) => parse_func_def(tokens.clone(), s.clone()),
    Some(TokenShape::ShKwService) => parse_service_def(tokens.clone(), s.clone()),
    Some(TokenShape::ShKwResource) => parse_resource_def(tokens.clone(), s.clone()),
    Some(TokenShape::ShKwData) => parse_data_def(tokens.clone(), s.clone()),
    Some(TokenShape::ShKwExtern) => parse_extern_decl(tokens.clone(), s.clone()),
    Some(TokenShape::ShKwPattern) => parse_func_def(tokens.clone(), s.clone()),
    Some(TokenShape::ShKwInterface) => parse_func_def(tokens.clone(), s.clone()),
    _ => Rc::new(ItemResult {
    item: Rc::new(Node {
    name: "<unknown>".to_string(),
    span: current_span(tokens.clone(), s.clone()),
    children: vec![],
    params: vec![],
    inferred: None,
    return_cardinality: Cardinality::Required,
    uses: vec![],
    body: None,
    collection_kind: None,
    connective: None,
    transport: None,
    properties: vec![],
    type_annotation: None,
    is_self_recursive: false,
    has_non_tail_self_call: false,
    match_pattern: None,
    expr_data: Rc::new(ExprData::NoExprData),
}),
    state: s.clone(),
    err: Some(parse_error("expected item declaration (type, fn, func, service, resource, data, extern, pattern, interface)".to_string(), current_span(tokens.clone(), s.clone()))),
}),
}
}
}

