pub fn parse_type_expr(tokens: Rc<Vec<Rc<Token>>>, state: Rc<ParserState>) -> Rc<TypeResult> {
    {
        let s = skip_newlines(tokens.clone(), state.clone());
let tok = peek(tokens.clone(), s.clone());
let sh = match tok.clone() {
    Some(t) => Some(t.shape.clone()),
    None => None,
};
match sh.clone() {
    Some(TokenShape::ShLBrace) => {
            let adv = advance(tokens.clone(), s.clone());
let inline_start = current_span(tokens.clone(), s.clone());
let r = parse_field_list(tokens.clone(), skip_newlines(tokens.clone(), adv.state.clone()));
if has_err(r.err.clone()) {
                return Rc::new(TypeResult {
    type_expr: leaf_type_node("".to_string(), inline_start.clone()),
    state: r.state.clone(),
    err: r.err.clone(),
})
}
let s2 = skip_newlines(tokens.clone(), r.state.clone());
let r2 = expect(tokens.clone(), s2.clone(), ExpectedToken::ExpectRBrace);
if has_err(r2.err.clone()) {
                return Rc::new(TypeResult {
    type_expr: leaf_type_node("".to_string(), inline_start.clone()),
    state: r2.state.clone(),
    err: r2.err.clone(),
})
}
let span = current_span(tokens.clone(), s.clone());
let te = Rc::new(Node {
    name: "".to_string(),
    span: span.clone(),
    children: { let mut __result = Vec::new(); for f in r.fields.clone().iter().cloned() { __result.push(field_to_child_node(f.clone())); } __result },
    connective: Some(Connective::Conj),
    collection_kind: None,
    params: vec![],
    inferred: None,
    return_cardinality: Cardinality::Required,
    uses: vec![],
    body: None,
    transport: None,
    properties: vec![],
    type_annotation: None,
    is_self_recursive: false,
    has_non_tail_self_call: false,
    match_pattern: None,
    expr_data: Rc::new(ExprData::NoExprData),
});
Rc::new(TypeResult {
    type_expr: te.clone(),
    state: r2.state.clone(),
    err: None,
})
},
    Some(TokenShape::ShKwFn) => {
            let adv = advance(tokens.clone(), s.clone());
let start_span = current_span(tokens.clone(), s.clone());
parse_callable_type_expr(tokens.clone(), adv.state.clone(), start_span.clone())
},
    Some(TokenShape::ShIdent) => {
            let n = tok.clone().unwrap().text.clone();
let adv = advance(tokens.clone(), s.clone());
let span = current_span(tokens.clone(), s.clone());
finish_type_expr_from_name(tokens.clone(), adv.state.clone(), n.clone(), span.clone())
},
    _ => Rc::new(TypeResult {
    type_expr: leaf_type_node("".to_string(), current_span(tokens.clone(), s.clone())),
    state: s.clone(),
    err: Some(parse_error("expected type expression".to_string(), current_span(tokens.clone(), s.clone()))),
}),
}
}
}

pub fn parse_callable_type_expr(tokens: Rc<Vec<Rc<Token>>>, state: Rc<ParserState>, start_span: Rc<SourceSpan>) -> Rc<TypeResult> {
    {
        let dummy_te = leaf_type_node("Callable".to_string(), start_span.clone());
let r = expect(tokens.clone(), state.clone(), ExpectedToken::ExpectLParen);
if has_err(r.err.clone()) {
            return Rc::new(TypeResult {
    type_expr: dummy_te.clone(),
    state: r.state.clone(),
    err: r.err.clone(),
})
}
let s = skip_newlines(tokens.clone(), r.state.clone());
let params_result = if peek_is_rparen(tokens.clone(), s.clone()) {
            Rc::new(ParamsResult {
    params: vec![],
    state: s.clone(),
    err: None,
})
} else {
            parse_callable_param_types(tokens.clone(), s.clone(), vec![])
};
if has_err(params_result.err.clone()) {
            return Rc::new(TypeResult {
    type_expr: dummy_te.clone(),
    state: params_result.state.clone(),
    err: params_result.err.clone(),
})
}
let s2 = skip_newlines(tokens.clone(), params_result.state.clone());
let r2 = expect(tokens.clone(), s2.clone(), ExpectedToken::ExpectRParen);
if has_err(r2.err.clone()) {
            return Rc::new(TypeResult {
    type_expr: dummy_te.clone(),
    state: r2.state.clone(),
    err: r2.err.clone(),
})
}
let r3 = expect(tokens.clone(), r2.state.clone(), ExpectedToken::ExpectArrow);
if has_err(r3.err.clone()) {
            return Rc::new(TypeResult {
    type_expr: dummy_te.clone(),
    state: r3.state.clone(),
    err: r3.err.clone(),
})
}
let ret = parse_type_expr(tokens.clone(), r3.state.clone());
if has_err(ret.err.clone()) {
            return Rc::new(TypeResult {
    type_expr: dummy_te.clone(),
    state: ret.state.clone(),
    err: ret.err.clone(),
})
}
let te = Rc::new(Node {
    name: "Callable".to_string(),
    span: start_span.clone(),
    children: vec![],
    connective: None,
    collection_kind: None,
    params: params_result.params.clone(),
    inferred: Some(Rc::new(InferredNode::Resolved {
    node: ret.type_expr.clone(),
})),
    return_cardinality: Cardinality::Required,
    uses: vec![],
    body: None,
    transport: None,
    properties: vec![],
    type_annotation: None,
    is_self_recursive: false,
    has_non_tail_self_call: false,
    match_pattern: None,
    expr_data: Rc::new(ExprData::NoExprData),
});
maybe_optional(tokens.clone(), ret.state.clone(), te.clone(), start_span.clone())
}
}

pub fn parse_callable_param_types(mut tokens: Rc<Vec<Rc<Token>>>, mut state: Rc<ParserState>, mut acc: Vec<Rc<Param>>) -> Rc<ParamsResult> {
    loop {
        let r = parse_type_expr(tokens.clone(), state.clone());
if has_err(r.err.clone()) {
            return Rc::new(ParamsResult {
    params: vec![],
    state: r.state.clone(),
    err: r.err.clone(),
})
}
let param = Rc::new(Param {
    name: "".to_string(),
    type_expr: r.type_expr.clone(),
    default_value: None,
    span: r.type_expr.clone().span.clone(),
});
acc = v2_rt::list_push(acc.clone(), param.clone());
let e = eat(tokens.clone(), r.state.clone(), ExpectedToken::ExpectComma);
if e.consumed.clone() {
            let s = skip_newlines(tokens.clone(), e.state.clone());
if peek_is_rparen(tokens.clone(), s.clone()) {
                break Rc::new(ParamsResult {
    params: acc.clone(),
    state: s.clone(),
    err: None,
});
} else {
                {
                    let __tco_0 = tokens.clone();
let __tco_1 = s.clone();
let __tco_2 = acc.clone();
tokens = __tco_0;
state = __tco_1;
acc = __tco_2;
continue;
}
}
} else {
            break Rc::new(ParamsResult {
    params: acc.clone(),
    state: r.state.clone(),
    err: None,
});
}
}
}

pub fn finish_type_expr_from_name(tokens: Rc<Vec<Rc<Token>>>, state: Rc<ParserState>, type_name: String, start_span: Rc<SourceSpan>) -> Rc<TypeResult> {
    {
        let dummy_te = leaf_type_node(type_name.clone(), start_span.clone());
let e = eat(tokens.clone(), state.clone(), ExpectedToken::ExpectLt);
if e.consumed.clone() {
            {
                let r = parse_type_expr(tokens.clone(), e.state.clone());
if has_err(r.err.clone()) {
                    return r.clone()
}
let first_arg = r.type_expr.clone();
let s = r.state.clone();
let type_args = collect_type_args(tokens.clone(), s.clone(), vec![first_arg.clone()]);
if has_err(type_args.err.clone()) {
                    return Rc::new(TypeResult {
    type_expr: dummy_te.clone(),
    state: type_args.state.clone(),
    err: type_args.err.clone(),
})
}
let r3 = expect(tokens.clone(), type_args.state.clone(), ExpectedToken::ExpectGt);
if has_err(r3.err.clone()) {
                    return Rc::new(TypeResult {
    type_expr: dummy_te.clone(),
    state: r3.state.clone(),
    err: r3.err.clone(),
})
}
let te = Rc::new(Node {
    name: type_name.clone(),
    span: start_span.clone(),
    children: type_args.args.clone(),
    connective: None,
    collection_kind: None,
    params: vec![],
    inferred: None,
    return_cardinality: Cardinality::Required,
    uses: vec![],
    body: None,
    transport: None,
    properties: vec![],
    type_annotation: None,
    is_self_recursive: false,
    has_non_tail_self_call: false,
    match_pattern: None,
    expr_data: Rc::new(ExprData::NoExprData),
});
maybe_optional(tokens.clone(), r3.state.clone(), te.clone(), start_span.clone())
}
} else {
            {
                let te = leaf_type_node(type_name.clone(), start_span.clone());
maybe_optional(tokens.clone(), state.clone(), te.clone(), start_span.clone())
}
}
}
}

#[derive(Debug, Clone, PartialEq)]
pub struct TypeParamsResult {
    pub params: Vec<Rc<Param>>,
    pub state: Rc<ParserState>,
}

pub fn parse_optional_type_params(tokens: Rc<Vec<Rc<Token>>>, state: Rc<ParserState>) -> Rc<TypeParamsResult> {
    {
        let e = eat(tokens.clone(), state.clone(), ExpectedToken::ExpectLt);
if e.consumed.clone() {
            {
                let params_result = collect_type_param_names(tokens.clone(), e.state.clone(), vec![]);
let r = expect(tokens.clone(), params_result.state.clone(), ExpectedToken::ExpectGt);
Rc::new(TypeParamsResult {
    params: params_result.params.clone(),
    state: r.state.clone(),
})
}
} else {
            Rc::new(TypeParamsResult {
    params: vec![],
    state: state.clone(),
})
}
}
}

pub fn collect_type_param_names(mut tokens: Rc<Vec<Rc<Token>>>, mut state: Rc<ParserState>, mut params: Vec<Rc<Param>>) -> Rc<TypeParamsResult> {
    loop {
        if is_ident(tokens.clone(), state.clone()) {
            let r = expect_ident(tokens.clone(), state.clone());
let span = current_span(tokens.clone(), r.state.clone());
let param = Rc::new(Param {
    name: r.name.clone(),
    type_expr: leaf_type_node(r.name.clone(), span.clone()),
    default_value: None,
    span: span.clone(),
});
let next_params = v2_rt::list_push(params.clone(), param.clone());
let e = eat(tokens.clone(), r.state.clone(), ExpectedToken::ExpectComma);
if e.consumed.clone() {
                {
                    let __tco_0 = tokens.clone();
let __tco_1 = e.state.clone();
let __tco_2 = next_params.clone();
tokens = __tco_0;
state = __tco_1;
params = __tco_2;
continue;
}
} else {
                break Rc::new(TypeParamsResult {
    params: next_params.clone(),
    state: r.state.clone(),
});
}
} else {
            break Rc::new(TypeParamsResult {
    params: params.clone(),
    state: state.clone(),
});
}
}
}

