pub fn is_container_name(name: String) -> bool {
    if (name.clone() == "List".to_string()) {
        true
} else {
        if (name.clone() == "Set".to_string()) {
            true
} else {
            if (name.clone() == "NonEmptyList".to_string()) {
                true
} else {
                if (name.clone() == "NonEmptySet".to_string()) {
                    true
} else {
                    false
}
}
}
}
}

pub fn node_to_name_str(n: Rc<Node>) -> String {
    stacker::maybe_grow(512 * 1024, 2 * 1024 * 1024, || {
        {
            let has_children = ((n.children.clone().len() as i64) > 0);
let is_optional = (n.return_cardinality.clone() == Cardinality::CardOptional);
if is_optional.clone() {
                v2_rt::concat("Optional_".to_string(), node_to_name_str(with_required_cardinality(n.clone())))
} else {
                if (n.name.clone() == "Map".to_string()) {
                    if ((n.children.clone().len() as i64) > 1) {
                        v2_rt::concat("Map_".to_string(), node_to_name_str(last_child_or_self(n.clone())))
} else {
                        n.name.clone()
}
} else {
                    if (n.name.clone() == "Refined".to_string()) {
                        if has_children.clone() {
                            node_to_name_str(first_child_or_self(n.clone()))
} else {
                            n.name.clone()
}
} else {
                        if is_container_name(n.name.clone()) {
                            if has_children.clone() {
                                v2_rt::concat("List_".to_string(), node_to_name_str(first_child_or_self(n.clone())))
} else {
                                n.name.clone()
}
} else {
                            if (n.name.clone() == "".to_string()) {
                                if node_is_product(n.clone()) {
                                    "Record".to_string()
} else {
                                    if node_is_coproduct(n.clone()) {
                                        "Union".to_string()
} else {
                                        n.name.clone()
}
}
} else {
                                n.name.clone()
}
}
}
}
}
}
    })
}

