pub fn parse_params(tokens: Rc<Vec<Rc<Token>>>, state: Rc<ParserState>) -> Rc<ParamsResult> {
    {
        let r = expect(tokens.clone(), state.clone(), ExpectedToken::ExpectLParen);
if has_err(r.err.clone()) {
            return Rc::new(ParamsResult {
    params: vec![],
    state: r.state.clone(),
    err: r.err.clone(),
})
}
let s = skip_newlines(tokens.clone(), r.state.clone());
if peek_is_rparen(tokens.clone(), s.clone()) {
            {
                let adv = advance(tokens.clone(), s.clone());
Rc::new(ParamsResult {
    params: vec![],
    state: adv.state.clone(),
    err: None,
})
}
} else {
            {
                let r = parse_param_list(tokens.clone(), s.clone());
if has_err(r.err.clone()) {
                    return r.clone()
}
let s = skip_newlines(tokens.clone(), r.state.clone());
let r2 = expect(tokens.clone(), s.clone(), ExpectedToken::ExpectRParen);
if has_err(r2.err.clone()) {
                    return Rc::new(ParamsResult {
    params: vec![],
    state: r2.state.clone(),
    err: r2.err.clone(),
})
}
Rc::new(ParamsResult {
    params: r.params.clone(),
    state: r2.state.clone(),
    err: None,
})
}
}
}
}

pub fn parse_param_list(tokens: Rc<Vec<Rc<Token>>>, state: Rc<ParserState>) -> Rc<ParamsResult> {
    parse_param_list_acc(tokens.clone(), state.clone(), vec![])
}

pub fn parse_param_list_acc(mut tokens: Rc<Vec<Rc<Token>>>, mut state: Rc<ParserState>, mut acc: Vec<Rc<Param>>) -> Rc<ParamsResult> {
    loop {
        let r = parse_param(tokens.clone(), state.clone());
if has_err(r.err.clone()) {
            return Rc::new(ParamsResult {
    params: vec![],
    state: r.state.clone(),
    err: r.err.clone(),
})
}
acc = v2_rt::list_push(acc.clone(), r.param.clone());
let s = r.state.clone();
let e = eat(tokens.clone(), s.clone(), ExpectedToken::ExpectComma);
if e.consumed.clone() {
            let s2 = skip_newlines(tokens.clone(), e.state.clone());
if peek_is_rparen(tokens.clone(), s2.clone()) {
                break Rc::new(ParamsResult {
    params: acc.clone(),
    state: s2.clone(),
    err: None,
});
} else {
                {
                    let __tco_0 = tokens.clone();
let __tco_1 = s2.clone();
let __tco_2 = acc.clone();
tokens = __tco_0;
state = __tco_1;
acc = __tco_2;
continue;
}
}
} else {
            break Rc::new(ParamsResult {
    params: acc.clone(),
    state: s.clone(),
    err: None,
});
}
}
}

pub fn parse_param(tokens: Rc<Vec<Rc<Token>>>, state: Rc<ParserState>) -> Rc<ParamResult> {
    {
        let start_span = current_span(tokens.clone(), state.clone());
let dummy_param = Rc::new(Param {
    name: "".to_string(),
    type_expr: leaf_type_node("".to_string(), start_span.clone()),
    default_value: None,
    span: start_span.clone(),
});
let r = expect_name(tokens.clone(), state.clone());
if has_err(r.err.clone()) {
            return Rc::new(ParamResult {
    param: dummy_param.clone(),
    state: r.state.clone(),
    err: r.err.clone(),
})
}
let name = r.name.clone();
let r2 = expect(tokens.clone(), r.state.clone(), ExpectedToken::ExpectColon);
if has_err(r2.err.clone()) {
            return Rc::new(ParamResult {
    param: dummy_param.clone(),
    state: r2.state.clone(),
    err: r2.err.clone(),
})
}
let r3 = parse_type_expr(tokens.clone(), r2.state.clone());
if has_err(r3.err.clone()) {
            return Rc::new(ParamResult {
    param: dummy_param.clone(),
    state: r3.state.clone(),
    err: r3.err.clone(),
})
}
let wr = try_where_clause(tokens.clone(), r3.state.clone(), r3.type_expr.clone(), start_span.clone());
if has_err(wr.err.clone()) {
            return Rc::new(ParamResult {
    param: dummy_param.clone(),
    state: wr.state.clone(),
    err: wr.err.clone(),
})
}
let type_expr = wr.type_expr.clone();
let s = wr.state.clone();
let e = eat(tokens.clone(), s.clone(), ExpectedToken::ExpectEq);
if e.consumed.clone() {
            {
                let r4 = parse_expr(tokens.clone(), e.state.clone());
if has_err(r4.err.clone()) {
                    return Rc::new(ParamResult {
    param: dummy_param.clone(),
    state: r4.state.clone(),
    err: r4.err.clone(),
})
}
let p = Rc::new(Param {
    name: name.clone(),
    type_expr: type_expr.clone(),
    default_value: Some(r4.expr.clone()),
    span: start_span.clone(),
});
Rc::new(ParamResult {
    param: p.clone(),
    state: r4.state.clone(),
    err: None,
})
}
} else {
            {
                let p = Rc::new(Param {
    name: name.clone(),
    type_expr: type_expr.clone(),
    default_value: None,
    span: start_span.clone(),
});
Rc::new(ParamResult {
    param: p.clone(),
    state: s.clone(),
    err: None,
})
}
}
}
}

pub fn parse_block(tokens: Rc<Vec<Rc<Token>>>, state: Rc<ParserState>) -> Rc<ExprResult> {
    {
        let dummy_expr = parse_recovery_placeholder();
let r = expect(tokens.clone(), state.clone(), ExpectedToken::ExpectLBrace);
if has_err(r.err.clone()) {
            return Rc::new(ExprResult {
    expr: dummy_expr.clone(),
    state: r.state.clone(),
    err: r.err.clone(),
})
}
let s = skip_newlines(tokens.clone(), r.state.clone());
let r = parse_stmts(tokens.clone(), s.clone());
if has_err(r.err.clone()) {
            return Rc::new(ExprResult {
    expr: dummy_expr.clone(),
    state: r.state.clone(),
    err: r.err.clone(),
})
}
let stmts = r.stmts.clone();
let s = skip_newlines(tokens.clone(), r.state.clone());
let r = expect(tokens.clone(), s.clone(), ExpectedToken::ExpectRBrace);
if has_err(r.err.clone()) {
            return Rc::new(ExprResult {
    expr: dummy_expr.clone(),
    state: r.state.clone(),
    err: r.err.clone(),
})
}
if ((stmts.clone().len() as i64) == 1) {
            Rc::new(ExprResult {
    expr: stmts.clone().first().cloned().clone().unwrap(),
    state: r.state.clone(),
    err: None,
})
} else {
            {
                let span = current_span(tokens.clone(), state.clone());
Rc::new(ExprResult {
    expr: make_expr_node(Rc::new(ExprData::ExprBlock), stmts.clone(), None, span.clone()),
    state: r.state.clone(),
    err: None,
})
}
}
}
}

pub fn parse_stmts(tokens: Rc<Vec<Rc<Token>>>, state: Rc<ParserState>) -> Rc<StmtsResult> {
    parse_stmts_acc(tokens.clone(), state.clone(), vec![])
}

pub fn parse_stmts_acc(mut tokens: Rc<Vec<Rc<Token>>>, mut state: Rc<ParserState>, mut acc: Vec<Rc<Node>>) -> Rc<StmtsResult> {
    loop {
        let s = skip_newlines(tokens.clone(), state.clone());
if ((peek_is_rbrace(tokens.clone(), s.clone()) || at_end(tokens.clone(), s.clone())) || peek_is_eof(tokens.clone(), s.clone())) {
            break Rc::new(StmtsResult {
    stmts: acc.clone(),
    state: s.clone(),
    err: None,
});
} else {
            let r = parse_stmt(tokens.clone(), s.clone());
if has_err(r.err.clone()) {
                return Rc::new(StmtsResult {
    stmts: acc.clone(),
    state: r.state.clone(),
    err: r.err.clone(),
})
}
{
                let __tco_0 = tokens.clone();
let __tco_1 = r.state.clone();
let __tco_2 = v2_rt::list_push(acc.clone(), r.expr.clone());
tokens = __tco_0;
state = __tco_1;
acc = __tco_2;
continue;
}
}
}
}

pub fn parse_stmt(tokens: Rc<Vec<Rc<Token>>>, state: Rc<ParserState>) -> Rc<ExprResult> {
    {
        let sh = peek_shape(tokens.clone(), state.clone());
match sh.clone() {
    Some(TokenShape::ShKwLet) => parse_let(tokens.clone(), state.clone()),
    Some(TokenShape::ShKwReturn) => parse_return(tokens.clone(), state.clone()),
    Some(TokenShape::ShIdent) => if peek_is_eq_after_ident(tokens.clone(), state.clone()) {
            parse_bare_assignment(tokens.clone(), state.clone())
} else {
            parse_expr(tokens.clone(), state.clone())
},
    _ => parse_expr(tokens.clone(), state.clone()),
}
}
}

pub fn peek_is_eq_after_ident(tokens: Rc<Vec<Rc<Token>>>, state: Rc<ParserState>) -> bool {
    if ((state.pos.clone() + 1) < (tokens.clone().len() as i64)) {
        {
            let next_tok = tokens.clone().get(((state.pos.clone() + 1)) as usize).cloned();
match next_tok.clone() {
    Some(t) => is_eq_shape(t.shape.clone()),
    None => false,
}
}
} else {
        false
}
}

pub fn is_constraint_bracket(tokens: Rc<Vec<Rc<Token>>>, state: Rc<ParserState>) -> bool {
    if ((state.pos.clone() + 1) < (tokens.clone().len() as i64)) {
        let next_tok = tokens.clone().get(((state.pos.clone() + 1)) as usize).cloned();
        match next_tok {
            Some(t) => if is_ident_shape(t.shape.clone()) { t.text.clone() == "after" || t.text.clone() == "when" } else { false },
            None => false,
        }
    } else { false }
}
pub fn parse_constraint_annotations(tokens: Rc<Vec<Rc<Token>>>, state: Rc<ParserState>) -> Rc<ConstraintsResult> {
    let e = eat(tokens.clone(), state.clone(), ExpectedToken::ExpectLBracket);
    if e.consumed.clone() {
        let r = parse_constraint_list(tokens.clone(), e.state.clone(), vec![]);
        if has_err(r.err.clone()) { return r }
        let r2 = expect(tokens.clone(), r.state.clone(), ExpectedToken::ExpectRBracket);
        if has_err(r2.err.clone()) { return Rc::new(ConstraintsResult { constraints: vec![], state: r2.state.clone(), err: r2.err.clone() }) }
        Rc::new(ConstraintsResult { constraints: r.constraints.clone(), state: r2.state.clone(), err: None })
    } else { Rc::new(ConstraintsResult { constraints: vec![], state: state.clone(), err: None }) }
}
pub fn parse_constraint_list(tokens: Rc<Vec<Rc<Token>>>, state: Rc<ParserState>, acc: Vec<Rc<FieldInit>>) -> Rc<ConstraintsResult> {
    let s = skip_newlines(tokens.clone(), state.clone());
    let tok = peek(tokens.clone(), s.clone());
    let is_ckw = match tok.clone() { Some(t) => is_ident_shape(t.shape.clone()) && (t.text.clone() == "after" || t.text.clone() == "when"), None => false };
    if !is_ckw { return Rc::new(ConstraintsResult { constraints: acc.clone(), state: s.clone(), err: None }) }
    let kw_name = tok.unwrap().text.clone();
    let adv = advance(tokens.clone(), s.clone());
    let r = parse_expr(tokens.clone(), adv.state.clone());
    if has_err(r.err.clone()) { return Rc::new(ConstraintsResult { constraints: vec![], state: r.state.clone(), err: r.err.clone() }) }
    let fi = Rc::new(FieldInit { name: kw_name.clone(), value: r.expr.clone() });
    let mut acc = acc.clone(); acc.push(fi);
    let ec = eat(tokens.clone(), r.state.clone(), ExpectedToken::ExpectComma);
    if ec.consumed.clone() { parse_constraint_list(tokens.clone(), ec.state.clone(), acc) }
    else { Rc::new(ConstraintsResult { constraints: acc.clone(), state: r.state.clone(), err: None }) }
}
pub fn try_constraint_annotations(tokens: Rc<Vec<Rc<Token>>>, state: Rc<ParserState>) -> Rc<ConstraintsResult> {
    if is_constraint_bracket(tokens.clone(), state.clone()) { parse_constraint_annotations(tokens.clone(), state.clone()) }
    else { Rc::new(ConstraintsResult { constraints: vec![], state: state.clone(), err: None }) }
}
pub fn peek_is_node_decl(tokens: Rc<Vec<Rc<Token>>>, state: Rc<ParserState>) -> bool {
    if ((state.pos.clone() + 2) < (tokens.clone().len() as i64)) {
        let t1 = tokens.clone().get(((state.pos.clone() + 1)) as usize).cloned();
        let t2 = tokens.clone().get(((state.pos.clone() + 2)) as usize).cloned();
        let name_ok = match t1 { Some(t) => is_ident_shape(t.shape.clone()) || is_name_keyword_shape(t.shape.clone()), None => false };
        let decl_ok = match t2 { Some(t) => is_colon_shape(t.shape.clone()) || is_lbracket_shape(t.shape.clone()), None => false };
        name_ok && decl_ok
    } else { false }
}
pub fn peek_text_is(tokens: Rc<Vec<Rc<Token>>>, state: Rc<ParserState>, expected: String) -> bool {
    match peek(tokens.clone(), state.clone()) { Some(t) => is_ident_shape(t.shape.clone()) && t.text.clone() == expected, None => false }
}
pub fn parse_node_decl(tokens: Rc<Vec<Rc<Token>>>, state: Rc<ParserState>) -> Rc<ExprResult> {
    let span = current_span(tokens.clone(), state.clone());
    let dummy_expr = parse_recovery_placeholder();
    let adv = advance(tokens.clone(), state.clone());
    let r = expect_name(tokens.clone(), adv.state.clone());
    if has_err(r.err.clone()) { return Rc::new(ExprResult { expr: dummy_expr.clone(), state: r.state.clone(), err: r.err.clone() }) }
    let name = r.name.clone();
    let cr = try_constraint_annotations(tokens.clone(), r.state.clone());
    if has_err(cr.err.clone()) { return Rc::new(ExprResult { expr: dummy_expr.clone(), state: cr.state.clone(), err: cr.err.clone() }) }
    let r2 = expect(tokens.clone(), cr.state.clone(), ExpectedToken::ExpectColon);
    if has_err(r2.err.clone()) { return Rc::new(ExprResult { expr: dummy_expr.clone(), state: r2.state.clone(), err: r2.err.clone() }) }
    let r3 = parse_expr(tokens.clone(), r2.state.clone());
    if has_err(r3.err.clone()) { return r3.clone() }
    Rc::new(ExprResult { expr: Rc::new(Node {
        name: "".to_string(), span: span.clone(), children: vec![r3.expr.clone()],
        connective: None, collection_kind: None, params: vec![], inferred: None,
        return_cardinality: Cardinality::Required, uses: vec![], body: None, transport: None,
        properties: cr.constraints.clone(), type_annotation: None, is_self_recursive: false,
        has_non_tail_self_call: false, match_pattern: None,
        expr_data: Rc::new(ExprData::ExprLet { name: name.clone() }),
    }), state: r3.state.clone(), err: None })
}

pub fn parse_bare_assignment(tokens: Rc<Vec<Rc<Token>>>, state: Rc<ParserState>) -> Rc<ExprResult> {
    {
        let span = current_span(tokens.clone(), state.clone());
let dummy_expr = parse_recovery_placeholder();
let r = expect_name(tokens.clone(), state.clone());
if has_err(r.err.clone()) {
            return Rc::new(ExprResult {
    expr: dummy_expr.clone(),
    state: r.state.clone(),
    err: r.err.clone(),
})
}
let name = r.name.clone();
let r2 = expect(tokens.clone(), r.state.clone(), ExpectedToken::ExpectEq);
if has_err(r2.err.clone()) {
            return Rc::new(ExprResult {
    expr: dummy_expr.clone(),
    state: r2.state.clone(),
    err: r2.err.clone(),
})
}
let r3 = parse_expr(tokens.clone(), r2.state.clone());
if has_err(r3.err.clone()) {
            return r3.clone()
}
let cr = try_constraint_annotations(tokens.clone(), r3.state.clone());
if has_err(cr.err.clone()) { return Rc::new(ExprResult { expr: dummy_expr.clone(), state: cr.state.clone(), err: cr.err.clone() }) }
let node = make_expr_node(Rc::new(ExprData::ExprLet { name: name.clone() }), vec![r3.expr.clone()], None, span.clone());
if (cr.constraints.clone().len() as i64) > 0 {
    let node = Rc::new(Node {
        name: node.name.clone(), span: node.span.clone(), children: node.children.clone(),
        params: node.params.clone(), inferred: node.inferred.clone(),
        return_cardinality: node.return_cardinality.clone(), uses: node.uses.clone(),
        body: node.body.clone(), collection_kind: node.collection_kind.clone(),
        connective: node.connective.clone(), transport: node.transport.clone(),
        properties: cr.constraints.clone(), type_annotation: node.type_annotation.clone(),
        is_self_recursive: node.is_self_recursive.clone(),
        has_non_tail_self_call: node.has_non_tail_self_call.clone(),
        match_pattern: node.match_pattern.clone(), expr_data: node.expr_data.clone(),
    });
    Rc::new(ExprResult { expr: node.clone(), state: cr.state.clone(), err: None })
} else {
    Rc::new(ExprResult { expr: node.clone(), state: cr.state.clone(), err: None })
}
}
}

pub fn parse_expr(tokens: Rc<Vec<Rc<Token>>>, state: Rc<ParserState>) -> Rc<ExprResult> {
    parse_expr_bp(tokens.clone(), state.clone(), 0)
}

pub fn parse_expr_bp(tokens: Rc<Vec<Rc<Token>>>, state: Rc<ParserState>, min_bp: i64) -> Rc<ExprResult> {
    {
        let r = parse_prefix(tokens.clone(), state.clone());
if has_err(r.err.clone()) {
            return r.clone()
}
let lhs = r.expr.clone();
let s = r.state.clone();
parse_expr_loop(tokens.clone(), s.clone(), lhs.clone(), min_bp.clone())
}
}

pub fn parse_expr_loop(mut tokens: Rc<Vec<Rc<Token>>>, mut state: Rc<ParserState>, mut lhs: Rc<Node>, mut min_bp: i64) -> Rc<ExprResult> {
    loop {
        if (at_end(tokens.clone(), state.clone()) || peek_is_eof(tokens.clone(), state.clone())) {
            break Rc::new(ExprResult {
    expr: lhs.clone(),
    state: state.clone(),
    err: None,
});
} else {
            let s = skip_continuation_newlines(tokens.clone(), state.clone());
let post = try_postfix(tokens.clone(), s.clone(), lhs.clone(), min_bp.clone());
if has_err(post.err.clone()) {
                break Rc::new(ExprResult {
    expr: lhs.clone(),
    state: post.state.clone(),
    err: post.err.clone(),
});
} else {
                if post.changed.clone() {
                    {
                        let __tco_0 = tokens.clone();
let __tco_1 = post.state.clone();
let __tco_2 = post.expr.clone();
let __tco_3 = min_bp.clone();
tokens = __tco_0;
state = __tco_1;
lhs = __tco_2;
min_bp = __tco_3;
continue;
}
} else {
                    let bp = infix_bp(tokens.clone(), s.clone());
match bp.clone() {
    Some(bps) => { if (bps.left.clone() < min_bp.clone()) {
                        break Rc::new(ExprResult {
    expr: lhs.clone(),
    state: s.clone(),
    err: None,
});
} else {
                        let adv = advance(tokens.clone(), s.clone());
let op_shape = adv.token.clone().shape.clone();
if is_dot_shape(op_shape.clone()) {
                            let r = expect_name(tokens.clone(), adv.state.clone());
if has_err(r.err.clone()) {
                                return Rc::new(ExprResult {
    expr: lhs.clone(),
    state: r.state.clone(),
    err: r.err.clone(),
})
}
let span = current_span(tokens.clone(), state.clone());
let new_lhs = make_expr_node(Rc::new(ExprData::ExprFieldAccess {
    field: r.name.clone(),
    summary: None,
}), vec![lhs.clone()], None, span.clone());
{
                                let __tco_0 = tokens.clone();
let __tco_1 = r.state.clone();
let __tco_2 = new_lhs.clone();
let __tco_3 = min_bp.clone();
tokens = __tco_0;
state = __tco_1;
lhs = __tco_2;
min_bp = __tco_3;
continue;
}
} else {
                            if is_pipe_arrow_shape(op_shape.clone()) {
                                let span = current_span(tokens.clone(), state.clone());
let r = parse_pipe_rhs(tokens.clone(), adv.state.clone(), lhs.clone(), span.clone());
if has_err(r.err.clone()) {
                                    return Rc::new(ExprResult {
    expr: r.expr.clone(),
    state: r.state.clone(),
    err: r.err.clone(),
})
}
{
                                    let __tco_0 = tokens.clone();
let __tco_1 = r.state.clone();
let __tco_2 = r.expr.clone();
let __tco_3 = min_bp.clone();
tokens = __tco_0;
state = __tco_1;
lhs = __tco_2;
min_bp = __tco_3;
continue;
}
} else {
                                let rhs_state = skip_newlines(tokens.clone(), adv.state.clone());
let r = parse_expr_bp(tokens.clone(), rhs_state.clone(), bps.right.clone());
if has_err(r.err.clone()) {
                                    return Rc::new(ExprResult {
    expr: r.expr.clone(),
    state: r.state.clone(),
    err: r.err.clone(),
})
}
let span = current_span(tokens.clone(), state.clone());
let binop = token_to_binop(adv.token.clone().shape.clone());
let new_lhs = make_expr_node(Rc::new(ExprData::ExprBinOp {
    op: binop.clone(),
}), vec![lhs.clone(), r.expr.clone()], None, span.clone());
{
                                    let __tco_0 = tokens.clone();
let __tco_1 = r.state.clone();
let __tco_2 = new_lhs.clone();
let __tco_3 = min_bp.clone();
tokens = __tco_0;
state = __tco_1;
lhs = __tco_2;
min_bp = __tco_3;
continue;
}
}
}
} },
    None => { break Rc::new(ExprResult {
    expr: lhs.clone(),
    state: s.clone(),
    err: None,
}); },
}
}
}
}
}
}

pub fn infix_bp(tokens: Rc<Vec<Rc<Token>>>, state: Rc<ParserState>) -> Option<Rc<BindingPower>> {
    {
        let sh = peek_shape(tokens.clone(), state.clone());
match sh.clone() {
    Some(TokenShape::ShNullCoalesce) => Some(Rc::new(BindingPower {
    left: 3,
    right: 4,
})),
    Some(TokenShape::ShOr) => Some(Rc::new(BindingPower {
    left: 5,
    right: 6,
})),
    Some(TokenShape::ShAnd) => Some(Rc::new(BindingPower {
    left: 7,
    right: 8,
})),
    Some(TokenShape::ShEqEq) => Some(Rc::new(BindingPower {
    left: 9,
    right: 10,
})),
    Some(TokenShape::ShNe) => Some(Rc::new(BindingPower {
    left: 9,
    right: 10,
})),
    Some(TokenShape::ShLt) => Some(Rc::new(BindingPower {
    left: 11,
    right: 12,
})),
    Some(TokenShape::ShGt) => Some(Rc::new(BindingPower {
    left: 11,
    right: 12,
})),
    Some(TokenShape::ShLe) => Some(Rc::new(BindingPower {
    left: 11,
    right: 12,
})),
    Some(TokenShape::ShGe) => Some(Rc::new(BindingPower {
    left: 11,
    right: 12,
})),
    Some(TokenShape::ShPlus) => Some(Rc::new(BindingPower {
    left: 13,
    right: 14,
})),
    Some(TokenShape::ShMinus) => Some(Rc::new(BindingPower {
    left: 13,
    right: 14,
})),
    Some(TokenShape::ShStar) => Some(Rc::new(BindingPower {
    left: 15,
    right: 16,
})),
    Some(TokenShape::ShSlash) => Some(Rc::new(BindingPower {
    left: 15,
    right: 16,
})),
    Some(TokenShape::ShPercent) => Some(Rc::new(BindingPower {
    left: 15,
    right: 16,
})),
    Some(TokenShape::ShPipeArrow) => Some(Rc::new(BindingPower {
    left: 17,
    right: 18,
})),
    Some(TokenShape::ShDot) => Some(Rc::new(BindingPower {
    left: 19,
    right: 20,
})),
    _ => None,
}
}
}

pub fn token_to_binop(shape: TokenShape) -> BinOpKind {
    match shape.clone() {
    TokenShape::ShPlus => BinOpKind::Add,
    TokenShape::ShMinus => BinOpKind::Sub,
    TokenShape::ShStar => BinOpKind::Mul,
    TokenShape::ShSlash => BinOpKind::Div,
    TokenShape::ShPercent => BinOpKind::Mod,
    TokenShape::ShEqEq => BinOpKind::BinEq,
    TokenShape::ShNe => BinOpKind::BinNe,
    TokenShape::ShLt => BinOpKind::BinLt,
    TokenShape::ShGt => BinOpKind::BinGt,
    TokenShape::ShLe => BinOpKind::BinLe,
    TokenShape::ShGe => BinOpKind::BinGe,
    TokenShape::ShAnd => BinOpKind::BinAnd,
    TokenShape::ShOr => BinOpKind::BinOr,
    TokenShape::ShNullCoalesce => BinOpKind::NullCoalesce,
    _ => BinOpKind::Add,
}
}

pub fn parse_pipe_rhs(tokens: Rc<Vec<Rc<Token>>>, state: Rc<ParserState>, receiver: Rc<Node>, span: Rc<SourceSpan>) -> Rc<ExprResult> {
    {
        let dummy_expr = parse_recovery_placeholder();
let r = expect_name(tokens.clone(), state.clone());
if has_err(r.err.clone()) {
            return Rc::new(ExprResult {
    expr: dummy_expr.clone(),
    state: r.state.clone(),
    err: r.err.clone(),
})
}
let method = r.name.clone();
let s = r.state.clone();
let s = skip_newlines(tokens.clone(), s.clone());
if peek_is_lparen(tokens.clone(), s.clone()) {
            {
                let r2 = parse_call_args(tokens.clone(), s.clone());
if has_err(r2.err.clone()) {
                    return Rc::new(ExprResult {
    expr: dummy_expr.clone(),
    state: r2.state.clone(),
    err: r2.err.clone(),
})
}
Rc::new(ExprResult {
    expr: make_expr_node(Rc::new(ExprData::ExprMethodCall {
    method: method.clone(),
    method_semantics: None,
}), v2_rt::concat(vec![receiver.clone()], { let mut __result = Vec::new(); for na in r2.args.clone().iter().cloned() { __result.push(make_arg_node(na.name.clone(), na.value.clone(), span.clone())); } __result }), None, span.clone()),
    state: r2.state.clone(),
    err: None,
})
}
} else {
            Rc::new(ExprResult {
    expr: make_expr_node(Rc::new(ExprData::ExprMethodCall {
    method: method.clone(),
    method_semantics: None,
}), vec![receiver.clone()], None, span.clone()),
    state: s.clone(),
    err: None,
})
}
}
}

pub fn parse_prefix(tokens: Rc<Vec<Rc<Token>>>, state: Rc<ParserState>) -> Rc<ExprResult> {
    {
        let sh = peek_shape(tokens.clone(), state.clone());
match sh.clone() {
    Some(TokenShape::ShBang) => {
            let adv = advance(tokens.clone(), state.clone());
let span = current_span(tokens.clone(), state.clone());
let r = parse_expr_bp(tokens.clone(), adv.state.clone(), 12);
if has_err(r.err.clone()) {
                return Rc::new(ExprResult {
    expr: r.expr.clone(),
    state: r.state.clone(),
    err: r.err.clone(),
})
}
Rc::new(ExprResult {
    expr: make_expr_node(Rc::new(ExprData::ExprUnaryOp {
    op: UnaryOpKind::Not,
}), vec![r.expr.clone()], None, span.clone()),
    state: r.state.clone(),
    err: None,
})
},
    Some(TokenShape::ShMinus) => {
            let adv = advance(tokens.clone(), state.clone());
let span = current_span(tokens.clone(), state.clone());
let r = parse_expr_bp(tokens.clone(), adv.state.clone(), 12);
if has_err(r.err.clone()) {
                return Rc::new(ExprResult {
    expr: r.expr.clone(),
    state: r.state.clone(),
    err: r.err.clone(),
})
}
Rc::new(ExprResult {
    expr: make_expr_node(Rc::new(ExprData::ExprUnaryOp {
    op: UnaryOpKind::Neg,
}), vec![r.expr.clone()], None, span.clone()),
    state: r.state.clone(),
    err: None,
})
},
    _ => parse_primary(tokens.clone(), state.clone()),
}
}
}

pub fn parse_primary(tokens: Rc<Vec<Rc<Token>>>, state: Rc<ParserState>) -> Rc<ExprResult> {
    {
        let tok = peek(tokens.clone(), state.clone());
let sh = match tok.clone() {
    Some(t) => Some(t.shape.clone()),
    None => None,
};
let span = current_span(tokens.clone(), state.clone());
match sh.clone() {
    Some(TokenShape::ShKwTrue) => {
            let adv = advance(tokens.clone(), state.clone());
Rc::new(ExprResult {
    expr: make_expr_node(Rc::new(ExprData::ExprLiteral {
    value: Rc::new(LiteralValue::LitBool {
    value: true,
}),
}), vec![], None, span.clone()),
    state: adv.state.clone(),
    err: None,
})
},
    Some(TokenShape::ShKwFalse) => {
            let adv = advance(tokens.clone(), state.clone());
Rc::new(ExprResult {
    expr: make_expr_node(Rc::new(ExprData::ExprLiteral {
    value: Rc::new(LiteralValue::LitBool {
    value: false,
}),
}), vec![], None, span.clone()),
    state: adv.state.clone(),
    err: None,
})
},
    Some(TokenShape::ShKwNone) => {
            let adv = advance(tokens.clone(), state.clone());
Rc::new(ExprResult {
    expr: make_expr_node(Rc::new(ExprData::ExprLiteral {
    value: Rc::new(LiteralValue::LitNull),
}), vec![], None, span.clone()),
    state: adv.state.clone(),
    err: None,
})
},
    Some(TokenShape::ShLitInt) => {
            let n_opt = v2_rt::parse_int(tok.clone().unwrap().text.clone());
let n = match n_opt.clone() {
    Some(v) => v.clone(),
    None => return Rc::new(ExprResult {
    expr: make_expr_error_node(ExprErrorKind::InternalExprError, v2_rt::concat(v2_rt::concat("internal: ShLitInt token text not parseable as int: '".to_string(), tok.clone().unwrap().text.clone()), "'".to_string()), current_span(tokens.clone(), state.clone())),
    state: state.clone(),
    err: None,
}),
};
let adv = advance(tokens.clone(), state.clone());
Rc::new(ExprResult {
    expr: make_expr_node(Rc::new(ExprData::ExprLiteral {
    value: Rc::new(LiteralValue::LitInt {
    value: n.clone(),
}),
}), vec![], None, span.clone()),
    state: adv.state.clone(),
    err: None,
})
},
    Some(TokenShape::ShLitFloat) => {
            let f = tok.clone().unwrap().text.clone();
let adv = advance(tokens.clone(), state.clone());
Rc::new(ExprResult {
    expr: make_expr_node(Rc::new(ExprData::ExprLiteral {
    value: Rc::new(LiteralValue::LitFloat {
    value: f.clone(),
}),
}), vec![], None, span.clone()),
    state: adv.state.clone(),
    err: None,
})
},
    Some(TokenShape::ShLitStr) => {
            let s = tok.clone().unwrap().text.clone();
let adv = advance(tokens.clone(), state.clone());
Rc::new(ExprResult {
    expr: make_expr_node(Rc::new(ExprData::ExprLiteral {
    value: Rc::new(LiteralValue::LitStr {
    value: s.clone(),
}),
}), vec![], None, span.clone()),
    state: adv.state.clone(),
    err: None,
})
},
    Some(TokenShape::ShStrBegin) => parse_string_interp(tokens.clone(), state.clone()),
    Some(TokenShape::ShIdent) => {
            let n = tok.clone().unwrap().text.clone();
parse_ident_expr(tokens.clone(), state.clone(), n.clone())
},
    Some(TokenShape::ShLParen) => parse_paren_expr(tokens.clone(), state.clone()),
    Some(TokenShape::ShLBracket) => parse_list_literal(tokens.clone(), state.clone()),
    Some(TokenShape::ShLBrace) => parse_brace_expr(tokens.clone(), state.clone()),
    Some(TokenShape::ShKwMatch) => parse_match(tokens.clone(), state.clone()),
    Some(TokenShape::ShKwIf) => parse_if(tokens.clone(), state.clone()),
    Some(TokenShape::ShKwFor) => parse_for(tokens.clone(), state.clone()),
    Some(TokenShape::ShKwLet) => parse_let(tokens.clone(), state.clone()),
    Some(TokenShape::ShKwReturn) => parse_return(tokens.clone(), state.clone()),
    Some(TokenShape::ShKwFn) => parse_fn_lambda(tokens.clone(), state.clone()),
    _ => {
            let kw_name = keyword_to_name(tokens.clone(), state.clone());
match kw_name.clone() {
    Some(n) => parse_ident_expr(tokens.clone(), state.clone(), n.clone()),
    None => {
                let tag = match sh.clone() {
    Some(shape) => shape_display_name(shape.clone()),
    None => "EOF".to_string(),
};
Rc::new(ExprResult {
    expr: parse_recovery_expr(span.clone(), format!("expected expression, found {}", tag.clone())),
    state: state.clone(),
    err: Some(parse_error(format!("expected expression, found {}", tag.clone()), span.clone())),
})
},
}
},
}
}
}

pub fn parse_lambda_body(tokens: Rc<Vec<Rc<Token>>>, state: Rc<ParserState>) -> Rc<ExprResult> {
    {
        let s = skip_newlines(tokens.clone(), state.clone());
let sh = peek_shape(tokens.clone(), s.clone());
let is_block = match sh.clone() {
    Some(TokenShape::ShKwLet) => true,
    Some(TokenShape::ShKwReturn) => true,
    _ => false,
};
if is_block.clone() {
            {
                let r = parse_lambda_stmts(tokens.clone(), s.clone(), vec![]);
if has_err(r.err.clone()) {
                    return Rc::new(ExprResult {
    expr: parse_recovery_placeholder(),
    state: r.state.clone(),
    err: r.err.clone(),
})
}
let span = current_span(tokens.clone(), s.clone());
if ((r.stmts.clone().len() as i64) == 1) {
                    Rc::new(ExprResult {
    expr: r.stmts.clone().first().cloned().clone().unwrap(),
    state: r.state.clone(),
    err: None,
})
} else {
                    Rc::new(ExprResult {
    expr: make_expr_node(Rc::new(ExprData::ExprBlock), r.stmts.clone(), None, span.clone()),
    state: r.state.clone(),
    err: None,
})
}
}
} else {
            parse_expr(tokens.clone(), s.clone())
}
}
}

pub fn parse_lambda_stmts(mut tokens: Rc<Vec<Rc<Token>>>, mut state: Rc<ParserState>, mut acc: Vec<Rc<Node>>) -> Rc<StmtsResult> {
    loop {
        let s = skip_newlines(tokens.clone(), state.clone());
if (((peek_is_rparen(tokens.clone(), s.clone()) || peek_is_rbrace(tokens.clone(), s.clone())) || at_end(tokens.clone(), s.clone())) || peek_is_eof(tokens.clone(), s.clone())) {
            break Rc::new(StmtsResult {
    stmts: acc.clone(),
    state: s.clone(),
    err: None,
});
} else {
            let r = parse_stmt(tokens.clone(), s.clone());
if has_err(r.err.clone()) {
                return Rc::new(StmtsResult {
    stmts: acc.clone(),
    state: r.state.clone(),
    err: r.err.clone(),
})
}
{
                let __tco_0 = tokens.clone();
let __tco_1 = r.state.clone();
let __tco_2 = v2_rt::list_push(acc.clone(), r.expr.clone());
tokens = __tco_0;
state = __tco_1;
acc = __tco_2;
continue;
}
}
}
}

pub fn parse_ident_expr(tokens: Rc<Vec<Rc<Token>>>, state: Rc<ParserState>, name: String) -> Rc<ExprResult> {
    {
        let span = current_span(tokens.clone(), state.clone());
let adv = advance(tokens.clone(), state.clone());
let s = adv.state.clone();
if peek_is_fat_arrow(tokens.clone(), s.clone()) {
            {
                let adv2 = advance(tokens.clone(), s.clone());
let r = parse_lambda_body(tokens.clone(), adv2.state.clone());
if has_err(r.err.clone()) {
                    return r.clone()
}
Rc::new(ExprResult {
    expr: make_expr_node(Rc::new(ExprData::ExprLambda {
    params: vec![name.clone()],
    semantics: None,
}), vec![r.expr.clone()], None, span.clone()),
    state: r.state.clone(),
    err: None,
})
}
} else {
            if (is_uppercase_start(name.clone()) && peek_is_lbrace(tokens.clone(), s.clone())) {
                parse_record_literal(tokens.clone(), s.clone(), name.clone(), span.clone())
} else {
                Rc::new(ExprResult {
    expr: make_expr_node(Rc::new(ExprData::ExprVar {
    name: name.clone(),
    binding_kind: None,
}), vec![], None, span.clone()),
    state: s.clone(),
    err: None,
})
}
}
}
}

pub fn is_uppercase_start(name: String) -> bool {
    {
        let ch = v2_rt::char_at(name.clone(), 0);
((ch.clone() >= "A".to_string()) && (ch.clone() <= "Z".to_string()))
}
}

pub fn try_postfix(tokens: Rc<Vec<Rc<Token>>>, state: Rc<ParserState>, lhs: Rc<Node>, min_bp: i64) -> Rc<PostfixResult> {
    {
        let tok = peek(tokens.clone(), state.clone());
let sh = match tok.clone() {
    Some(t) => Some(t.shape.clone()),
    None => None,
};
let span = current_span(tokens.clone(), state.clone());
match sh.clone() {
    Some(TokenShape::ShLParen) => if (14 < min_bp.clone()) {
            Rc::new(PostfixResult {
    expr: lhs.clone(),
    changed: false,
    state: state.clone(),
    err: None,
})
} else {
            {
                let r = parse_call_args(tokens.clone(), state.clone());
if has_err(r.err.clone()) {
                    return Rc::new(PostfixResult {
    expr: lhs.clone(),
    changed: false,
    state: r.state.clone(),
    err: r.err.clone(),
})
}
let call_expr = make_call_expr(lhs.clone(), r.args.clone(), span.clone());
Rc::new(PostfixResult {
    expr: call_expr.clone(),
    changed: true,
    state: r.state.clone(),
    err: None,
})
}
},
    Some(TokenShape::ShIdent) => if (tok.clone().unwrap().text.clone() == "as".to_string()) {
            if (13 < min_bp.clone()) {
                Rc::new(PostfixResult {
    expr: lhs.clone(),
    changed: false,
    state: state.clone(),
    err: None,
})
} else {
                {
                    let adv = advance(tokens.clone(), state.clone());
let r = parse_type_expr(tokens.clone(), adv.state.clone());
if has_err(r.err.clone()) {
                        return Rc::new(PostfixResult {
    expr: lhs.clone(),
    changed: false,
    state: r.state.clone(),
    err: r.err.clone(),
})
}
Rc::new(PostfixResult {
    expr: make_expr_node(Rc::new(ExprData::ExprCast), vec![lhs.clone(), r.type_expr.clone()], None, span.clone()),
    changed: true,
    state: r.state.clone(),
    err: None,
})
}
}
} else {
            Rc::new(PostfixResult {
    expr: lhs.clone(),
    changed: false,
    state: state.clone(),
    err: None,
})
},
    Some(TokenShape::ShLBracket) => if (14 < min_bp.clone()) {
            Rc::new(PostfixResult {
    expr: lhs.clone(),
    changed: false,
    state: state.clone(),
    err: None,
})
} else if is_constraint_bracket(tokens.clone(), state.clone()) {
            Rc::new(PostfixResult {
    expr: lhs.clone(),
    changed: false,
    state: state.clone(),
    err: None,
})
} else {
            {
                let r = parse_index_or_slice(tokens.clone(), state.clone(), lhs.clone(), span.clone());
if has_err(r.err.clone()) {
                    return Rc::new(PostfixResult {
    expr: lhs.clone(),
    changed: false,
    state: r.state.clone(),
    err: r.err.clone(),
})
}
Rc::new(PostfixResult {
    expr: r.expr.clone(),
    changed: true,
    state: r.state.clone(),
    err: None,
})
}
},
    Some(TokenShape::ShLBrace) => match (*lhs.expr_data.clone()).clone() {
    ExprData::ExprVar { name: n, .. } => if (is_uppercase_start(n.clone()) && (14 <= min_bp.clone())) {
            Rc::new(PostfixResult {
    expr: lhs.clone(),
    changed: false,
    state: state.clone(),
    err: None,
})
} else {
            if is_uppercase_start(n.clone()) {
                {
                    let r = parse_record_literal(tokens.clone(), state.clone(), n.clone(), lhs.span.clone());
if has_err(r.err.clone()) {
                        return Rc::new(PostfixResult {
    expr: lhs.clone(),
    changed: false,
    state: r.state.clone(),
    err: r.err.clone(),
})
}
Rc::new(PostfixResult {
    expr: r.expr.clone(),
    changed: true,
    state: r.state.clone(),
    err: None,
})
}
} else {
                Rc::new(PostfixResult {
    expr: lhs.clone(),
    changed: false,
    state: state.clone(),
    err: None,
})
}
},
    _ => Rc::new(PostfixResult {
    expr: lhs.clone(),
    changed: false,
    state: state.clone(),
    err: None,
}),
},
    _ => Rc::new(PostfixResult {
    expr: lhs.clone(),
    changed: false,
    state: state.clone(),
    err: None,
}),
}
}
}

pub fn make_call_expr(lhs: Rc<Node>, args: Vec<Rc<NamedArg>>, span: Rc<SourceSpan>) -> Rc<Node> {
    {
        let arg_children = { let mut __result = Vec::new(); for na in args.clone().iter().cloned() { __result.push(make_arg_node(na.name.clone(), na.value.clone(), span.clone())); } __result };
match (*lhs.expr_data.clone()).clone() {
    ExprData::ExprVar { name: n, .. } => make_expr_node(Rc::new(ExprData::ExprCall {
    func: n.clone(),
    call_semantics: None,
}), arg_children.clone(), None, span.clone()),
    ExprData::ExprFieldAccess { field: f, .. } => make_expr_node(Rc::new(ExprData::ExprMethodCall {
    method: f.clone(),
    method_semantics: None,
}), v2_rt::concat(vec![lhs.children.clone().first().cloned().clone().unwrap()], arg_children.clone()), None, span.clone()),
    _ => make_expr_node(Rc::new(ExprData::ExprCall {
    func: "<expr>".to_string(),
    call_semantics: None,
}), arg_children.clone(), None, span.clone()),
}
}
}

pub fn parse_index_or_slice(tokens: Rc<Vec<Rc<Token>>>, state: Rc<ParserState>, base: Rc<Node>, span: Rc<SourceSpan>) -> Rc<ExprResult> {
    {
        let dummy_expr = parse_recovery_placeholder();
let r = expect(tokens.clone(), state.clone(), ExpectedToken::ExpectLBracket);
if has_err(r.err.clone()) {
            return Rc::new(ExprResult {
    expr: dummy_expr.clone(),
    state: r.state.clone(),
    err: r.err.clone(),
})
}
let s = r.state.clone();
let r = parse_expr(tokens.clone(), s.clone());
if has_err(r.err.clone()) {
            return Rc::new(ExprResult {
    expr: r.expr.clone(),
    state: r.state.clone(),
    err: r.err.clone(),
})
}
let first_expr = r.expr.clone();
let s = r.state.clone();
if peek_is_dot_dot(tokens.clone(), s.clone()) {
            {
                let adv = advance(tokens.clone(), s.clone());
let r = parse_expr(tokens.clone(), adv.state.clone());
if has_err(r.err.clone()) {
                    return Rc::new(ExprResult {
    expr: r.expr.clone(),
    state: r.state.clone(),
    err: r.err.clone(),
})
}
let end_expr = r.expr.clone();
let s = r.state.clone();
let r = expect(tokens.clone(), s.clone(), ExpectedToken::ExpectRBracket);
if has_err(r.err.clone()) {
                    return Rc::new(ExprResult {
    expr: dummy_expr.clone(),
    state: r.state.clone(),
    err: r.err.clone(),
})
}
Rc::new(ExprResult {
    expr: make_expr_node(Rc::new(ExprData::ExprSlice), vec![base.clone(), first_expr.clone(), end_expr.clone()], None, span.clone()),
    state: r.state.clone(),
    err: None,
})
}
} else {
            {
                let r = expect(tokens.clone(), s.clone(), ExpectedToken::ExpectRBracket);
if has_err(r.err.clone()) {
                    return Rc::new(ExprResult {
    expr: dummy_expr.clone(),
    state: r.state.clone(),
    err: r.err.clone(),
})
}
Rc::new(ExprResult {
    expr: make_expr_node(Rc::new(ExprData::ExprIndex), vec![base.clone(), first_expr.clone()], None, span.clone()),
    state: r.state.clone(),
    err: None,
})
}
}
}
}

pub fn parse_call_args(tokens: Rc<Vec<Rc<Token>>>, state: Rc<ParserState>) -> Rc<ArgsResult> {
    {
        let r = expect(tokens.clone(), state.clone(), ExpectedToken::ExpectLParen);
if has_err(r.err.clone()) {
            return Rc::new(ArgsResult {
    args: vec![],
    state: r.state.clone(),
    err: r.err.clone(),
})
}
let s = skip_newlines(tokens.clone(), r.state.clone());
if peek_is_rparen(tokens.clone(), s.clone()) {
            {
                let adv = advance(tokens.clone(), s.clone());
Rc::new(ArgsResult {
    args: vec![],
    state: adv.state.clone(),
    err: None,
})
}
} else {
            {
                let r = parse_arg_list(tokens.clone(), s.clone());
if has_err(r.err.clone()) {
                    return r.clone()
}
let s = skip_newlines(tokens.clone(), r.state.clone());
let r2 = expect(tokens.clone(), s.clone(), ExpectedToken::ExpectRParen);
if has_err(r2.err.clone()) {
                    return Rc::new(ArgsResult {
    args: vec![],
    state: r2.state.clone(),
    err: r2.err.clone(),
})
}
Rc::new(ArgsResult {
    args: r.args.clone(),
    state: r2.state.clone(),
    err: None,
})
}
}
}
}

pub fn parse_arg_list(tokens: Rc<Vec<Rc<Token>>>, state: Rc<ParserState>) -> Rc<ArgsResult> {
    parse_arg_list_acc(tokens.clone(), state.clone(), vec![])
}

pub fn parse_arg_list_acc(mut tokens: Rc<Vec<Rc<Token>>>, mut state: Rc<ParserState>, mut acc: Vec<Rc<NamedArg>>) -> Rc<ArgsResult> {
    loop {
        let s = skip_newlines(tokens.clone(), state.clone());
let r = parse_single_arg(tokens.clone(), s.clone());
if has_err(r.err.clone()) {
            return Rc::new(ArgsResult {
    args: vec![],
    state: r.state.clone(),
    err: r.err.clone(),
})
}
acc = v2_rt::list_push(acc.clone(), r.arg.clone());
let s = r.state.clone();
let e = eat(tokens.clone(), s.clone(), ExpectedToken::ExpectComma);
if e.consumed.clone() {
            let s2 = skip_newlines(tokens.clone(), e.state.clone());
if peek_is_rparen(tokens.clone(), s2.clone()) {
                break Rc::new(ArgsResult {
    args: acc.clone(),
    state: s2.clone(),
    err: None,
});
} else {
                {
                    let __tco_0 = tokens.clone();
let __tco_1 = s2.clone();
let __tco_2 = acc.clone();
tokens = __tco_0;
state = __tco_1;
acc = __tco_2;
continue;
}
}
} else {
            break Rc::new(ArgsResult {
    args: acc.clone(),
    state: s.clone(),
    err: None,
});
}
}
}

pub fn parse_single_arg(tokens: Rc<Vec<Rc<Token>>>, state: Rc<ParserState>) -> Rc<ArgResult> {
    {
        let dummy_arg = Rc::new(NamedArg {
    name: None,
    value: parse_recovery_placeholder(),
});
let is_name_token = (is_ident(tokens.clone(), state.clone()) || is_keyword_name(tokens.clone(), state.clone()));
if is_name_token.clone() {
            {
                let save_pos = state.pos.clone();
let name_r = expect_name(tokens.clone(), state.clone());
if has_err(name_r.err.clone()) {
                    {
                        let r = parse_expr(tokens.clone(), state.clone());
if has_err(r.err.clone()) {
                            return Rc::new(ArgResult {
    arg: dummy_arg.clone(),
    state: r.state.clone(),
    err: r.err.clone(),
})
}
let arg = Rc::new(NamedArg {
    name: None,
    value: r.expr.clone(),
});
Rc::new(ArgResult {
    arg: arg.clone(),
    state: r.state.clone(),
    err: None,
})
}
} else {
                    if peek_is_colon(tokens.clone(), name_r.state.clone()) {
                        {
                            let adv = advance(tokens.clone(), name_r.state.clone());
let r = parse_expr(tokens.clone(), adv.state.clone());
if has_err(r.err.clone()) {
                                return Rc::new(ArgResult {
    arg: dummy_arg.clone(),
    state: r.state.clone(),
    err: r.err.clone(),
})
}
let arg = Rc::new(NamedArg {
    name: Some(name_r.name.clone()),
    value: r.expr.clone(),
});
Rc::new(ArgResult {
    arg: arg.clone(),
    state: r.state.clone(),
    err: None,
})
}
} else {
                        {
                            let restored = Rc::new(ParserState { pos: save_pos.clone(), ..(*state.clone()).clone() });
let r = parse_expr(tokens.clone(), restored.clone());
if has_err(r.err.clone()) {
                                return Rc::new(ArgResult {
    arg: dummy_arg.clone(),
    state: r.state.clone(),
    err: r.err.clone(),
})
}
let arg = Rc::new(NamedArg {
    name: None,
    value: r.expr.clone(),
});
Rc::new(ArgResult {
    arg: arg.clone(),
    state: r.state.clone(),
    err: None,
})
}
}
}
}
} else {
            {
                let r = parse_expr(tokens.clone(), state.clone());
if has_err(r.err.clone()) {
                    return Rc::new(ArgResult {
    arg: dummy_arg.clone(),
    state: r.state.clone(),
    err: r.err.clone(),
})
}
let arg = Rc::new(NamedArg {
    name: None,
    value: r.expr.clone(),
});
Rc::new(ArgResult {
    arg: arg.clone(),
    state: r.state.clone(),
    err: None,
})
}
}
}
}

pub fn parse_match(tokens: Rc<Vec<Rc<Token>>>, state: Rc<ParserState>) -> Rc<ExprResult> {
    {
        let span = current_span(tokens.clone(), state.clone());
let dummy_expr = parse_recovery_placeholder();
let r = expect(tokens.clone(), state.clone(), ExpectedToken::ExpectKwMatch);
if has_err(r.err.clone()) {
            return Rc::new(ExprResult {
    expr: dummy_expr.clone(),
    state: r.state.clone(),
    err: r.err.clone(),
})
}
let r = parse_expr_no_brace(tokens.clone(), r.state.clone());
if has_err(r.err.clone()) {
            return r.clone()
}
let scrutinee = r.expr.clone();
let r = expect(tokens.clone(), skip_newlines(tokens.clone(), r.state.clone()), ExpectedToken::ExpectLBrace);
if has_err(r.err.clone()) {
            return Rc::new(ExprResult {
    expr: dummy_expr.clone(),
    state: r.state.clone(),
    err: r.err.clone(),
})
}
let r = parse_match_arms(tokens.clone(), skip_newlines(tokens.clone(), r.state.clone()));
if has_err(r.err.clone()) {
            return Rc::new(ExprResult {
    expr: dummy_expr.clone(),
    state: r.state.clone(),
    err: r.err.clone(),
})
}
let arms = r.arms.clone();
let r = expect(tokens.clone(), skip_newlines(tokens.clone(), r.state.clone()), ExpectedToken::ExpectRBrace);
if has_err(r.err.clone()) {
            return Rc::new(ExprResult {
    expr: dummy_expr.clone(),
    state: r.state.clone(),
    err: r.err.clone(),
})
}
Rc::new(ExprResult {
    expr: make_expr_node(Rc::new(ExprData::ExprMatch), v2_rt::concat(vec![scrutinee.clone()], { let mut __result = Vec::new(); for arm in arms.clone().iter().cloned() { __result.push(make_arm_node(arm.pattern.clone(), arm.guard.clone(), arm.body.clone(), span.clone())); } __result }), None, span.clone()),
    state: r.state.clone(),
    err: None,
})
}
}

pub fn parse_expr_no_brace(tokens: Rc<Vec<Rc<Token>>>, state: Rc<ParserState>) -> Rc<ExprResult> {
    parse_expr_bp_no_brace(tokens.clone(), state.clone(), 0)
}

pub fn parse_expr_bp_no_brace(tokens: Rc<Vec<Rc<Token>>>, state: Rc<ParserState>, min_bp: i64) -> Rc<ExprResult> {
    {
        let r = parse_prefix(tokens.clone(), state.clone());
if has_err(r.err.clone()) {
            return r.clone()
}
let lhs = r.expr.clone();
parse_expr_loop_no_brace(tokens.clone(), r.state.clone(), lhs.clone(), min_bp.clone())
}
}

pub fn parse_expr_loop_no_brace(mut tokens: Rc<Vec<Rc<Token>>>, mut state: Rc<ParserState>, mut lhs: Rc<Node>, mut min_bp: i64) -> Rc<ExprResult> {
    loop {
        if ((at_end(tokens.clone(), state.clone()) || peek_is_eof(tokens.clone(), state.clone())) || peek_is_lbrace(tokens.clone(), state.clone())) {
            break Rc::new(ExprResult {
    expr: lhs.clone(),
    state: state.clone(),
    err: None,
});
} else {
            let s = skip_continuation_newlines(tokens.clone(), state.clone());
if (peek_is_lparen(tokens.clone(), s.clone()) && (14 >= min_bp.clone())) {
                let r = parse_call_args(tokens.clone(), s.clone());
if has_err(r.err.clone()) {
                    return Rc::new(ExprResult {
    expr: lhs.clone(),
    state: r.state.clone(),
    err: r.err.clone(),
})
}
let span = current_span(tokens.clone(), s.clone());
let new_lhs = make_call_expr(lhs.clone(), r.args.clone(), span.clone());
{
                    let __tco_0 = tokens.clone();
let __tco_1 = r.state.clone();
let __tco_2 = new_lhs.clone();
let __tco_3 = min_bp.clone();
tokens = __tco_0;
state = __tco_1;
lhs = __tco_2;
min_bp = __tco_3;
continue;
}
} else {
                if (peek_is_lbracket(tokens.clone(), s.clone()) && (14 >= min_bp.clone())) {
                    let span = current_span(tokens.clone(), s.clone());
let r = parse_index_or_slice(tokens.clone(), s.clone(), lhs.clone(), span.clone());
if has_err(r.err.clone()) {
                        return Rc::new(ExprResult {
    expr: r.expr.clone(),
    state: r.state.clone(),
    err: r.err.clone(),
})
}
{
                        let __tco_0 = tokens.clone();
let __tco_1 = r.state.clone();
let __tco_2 = r.expr.clone();
let __tco_3 = min_bp.clone();
tokens = __tco_0;
state = __tco_1;
lhs = __tco_2;
min_bp = __tco_3;
continue;
}
} else {
                    let bp = infix_bp(tokens.clone(), s.clone());
match bp.clone() {
    Some(bps) => { if (bps.left.clone() < min_bp.clone()) {
                        break Rc::new(ExprResult {
    expr: lhs.clone(),
    state: s.clone(),
    err: None,
});
} else {
                        let adv = advance(tokens.clone(), s.clone());
let op_shape = adv.token.clone().shape.clone();
if is_dot_shape(op_shape.clone()) {
                            let r = expect_name(tokens.clone(), adv.state.clone());
if has_err(r.err.clone()) {
                                return Rc::new(ExprResult {
    expr: lhs.clone(),
    state: r.state.clone(),
    err: r.err.clone(),
})
}
let span = current_span(tokens.clone(), s.clone());
let new_lhs = make_expr_node(Rc::new(ExprData::ExprFieldAccess {
    field: r.name.clone(),
    summary: None,
}), vec![lhs.clone()], None, span.clone());
{
                                let __tco_0 = tokens.clone();
let __tco_1 = r.state.clone();
let __tco_2 = new_lhs.clone();
let __tco_3 = min_bp.clone();
tokens = __tco_0;
state = __tco_1;
lhs = __tco_2;
min_bp = __tco_3;
continue;
}
} else {
                            if is_pipe_arrow_shape(op_shape.clone()) {
                                let span = current_span(tokens.clone(), s.clone());
let r = parse_pipe_rhs(tokens.clone(), adv.state.clone(), lhs.clone(), span.clone());
if has_err(r.err.clone()) {
                                    return Rc::new(ExprResult {
    expr: r.expr.clone(),
    state: r.state.clone(),
    err: r.err.clone(),
})
}
{
                                    let __tco_0 = tokens.clone();
let __tco_1 = r.state.clone();
let __tco_2 = r.expr.clone();
let __tco_3 = min_bp.clone();
tokens = __tco_0;
state = __tco_1;
lhs = __tco_2;
min_bp = __tco_3;
continue;
}
} else {
                                let rhs_state = skip_newlines(tokens.clone(), adv.state.clone());
let r = parse_expr_bp_no_brace(tokens.clone(), rhs_state.clone(), bps.right.clone());
if has_err(r.err.clone()) {
                                    return Rc::new(ExprResult {
    expr: r.expr.clone(),
    state: r.state.clone(),
    err: r.err.clone(),
})
}
let span = current_span(tokens.clone(), s.clone());
let binop = token_to_binop(adv.token.clone().shape.clone());
let new_lhs = make_expr_node(Rc::new(ExprData::ExprBinOp {
    op: binop.clone(),
}), vec![lhs.clone(), r.expr.clone()], None, span.clone());
{
                                    let __tco_0 = tokens.clone();
let __tco_1 = r.state.clone();
let __tco_2 = new_lhs.clone();
let __tco_3 = min_bp.clone();
tokens = __tco_0;
state = __tco_1;
lhs = __tco_2;
min_bp = __tco_3;
continue;
}
}
}
} },
    None => { break Rc::new(ExprResult {
    expr: lhs.clone(),
    state: s.clone(),
    err: None,
}); },
}
}
}
}
}
}

pub fn parse_match_arms(tokens: Rc<Vec<Rc<Token>>>, state: Rc<ParserState>) -> Rc<ArmsResult> {
    parse_match_arms_acc(tokens.clone(), state.clone(), vec![])
}

pub fn parse_match_arms_acc(mut tokens: Rc<Vec<Rc<Token>>>, mut state: Rc<ParserState>, mut acc: Vec<Rc<MatchArm>>) -> Rc<ArmsResult> {
    loop {
        let s = skip_newlines(tokens.clone(), state.clone());
if (peek_is_rbrace(tokens.clone(), s.clone()) || at_end(tokens.clone(), s.clone())) {
            break Rc::new(ArmsResult {
    arms: acc.clone(),
    state: s.clone(),
    err: None,
});
} else {
            let r = parse_match_arm(tokens.clone(), s.clone());
if has_err(r.err.clone()) {
                return Rc::new(ArmsResult {
    arms: acc.clone(),
    state: r.state.clone(),
    err: r.err.clone(),
})
}
let e = eat(tokens.clone(), r.state.clone(), ExpectedToken::ExpectComma);
let s2 = skip_newlines(tokens.clone(), if e.consumed.clone() {
                e.state.clone()
} else {
                r.state.clone()
});
{
                let __tco_0 = tokens.clone();
let __tco_1 = s2.clone();
let __tco_2 = v2_rt::list_push(acc.clone(), r.arm.clone());
tokens = __tco_0;
state = __tco_1;
acc = __tco_2;
continue;
}
}
}
}

pub fn parse_match_arm(tokens: Rc<Vec<Rc<Token>>>, state: Rc<ParserState>) -> Rc<ArmResult> {
    {
        let dummy_arm = Rc::new(MatchArm {
    pattern: Rc::new(MatchPattern::Wildcard),
    guard: None,
    body: parse_recovery_placeholder(),
});
let r = parse_pattern(tokens.clone(), state.clone());
if has_err(r.err.clone()) {
            return Rc::new(ArmResult {
    arm: dummy_arm.clone(),
    state: r.state.clone(),
    err: r.err.clone(),
})
}
let pat = r.pattern.clone();
let s = r.state.clone();
let guard_r = parse_optional_guard(tokens.clone(), s.clone());
if has_err(guard_r.err.clone()) {
            return Rc::new(ArmResult {
    arm: dummy_arm.clone(),
    state: guard_r.state.clone(),
    err: guard_r.err.clone(),
})
}
let guard = guard_r.guard.clone();
let s = guard_r.state.clone();
let r = expect(tokens.clone(), s.clone(), ExpectedToken::ExpectFatArrow);
if has_err(r.err.clone()) {
            return Rc::new(ArmResult {
    arm: dummy_arm.clone(),
    state: r.state.clone(),
    err: r.err.clone(),
})
}
let s = skip_newlines(tokens.clone(), r.state.clone());
let r = if peek_is_lbrace(tokens.clone(), s.clone()) {
            parse_block(tokens.clone(), s.clone())
} else {
            parse_match_arm_body(tokens.clone(), s.clone())
};
if has_err(r.err.clone()) {
            return Rc::new(ArmResult {
    arm: dummy_arm.clone(),
    state: r.state.clone(),
    err: r.err.clone(),
})
}
let arm = Rc::new(MatchArm {
    pattern: pat.clone(),
    guard: guard.clone(),
    body: r.expr.clone(),
});
Rc::new(ArmResult {
    arm: arm.clone(),
    state: r.state.clone(),
    err: None,
})
}
}

pub fn parse_match_arm_body(tokens: Rc<Vec<Rc<Token>>>, state: Rc<ParserState>) -> Rc<ExprResult> {
    {
        let sh = peek_shape(tokens.clone(), state.clone());
let is_block = match sh.clone() {
    Some(TokenShape::ShKwLet) => true,
    Some(TokenShape::ShKwReturn) => true,
    _ => false,
};
if is_block.clone() {
            {
                let r = parse_match_arm_stmts(tokens.clone(), state.clone(), vec![]);
if has_err(r.err.clone()) {
                    return Rc::new(ExprResult {
    expr: parse_recovery_placeholder(),
    state: r.state.clone(),
    err: r.err.clone(),
})
}
let span = current_span(tokens.clone(), state.clone());
if ((r.stmts.clone().len() as i64) == 1) {
                    Rc::new(ExprResult {
    expr: r.stmts.clone().first().cloned().clone().unwrap(),
    state: r.state.clone(),
    err: None,
})
} else {
                    Rc::new(ExprResult {
    expr: make_expr_node(Rc::new(ExprData::ExprBlock), r.stmts.clone(), None, span.clone()),
    state: r.state.clone(),
    err: None,
})
}
}
} else {
            parse_expr(tokens.clone(), state.clone())
}
}
}

