pub fn looks_like_arm_start(tokens: Rc<Vec<Rc<Token>>>, state: Rc<ParserState>) -> bool {
    {
        let tok = peek(tokens.clone(), state.clone());
let sh = match tok.clone() {
    Some(t) => Some(t.shape.clone()),
    None => None,
};
match sh.clone() {
    Some(TokenShape::ShIdent) => {
            let n = tok.clone().unwrap().text.clone();
if (n.clone() == "_".to_string()) {
                peek_is_fat_arrow_at(tokens.clone(), state.clone(), 1)
} else {
                if is_uppercase_start(n.clone()) {
                    if peek_is_fat_arrow_at(tokens.clone(), state.clone(), 1) {
                        true
} else {
                        if peek_is_expected_at(tokens.clone(), state.clone(), 1, ExpectedToken::ExpectLBrace) {
                            scan_for_fat_arrow_after_braces(tokens.clone(), state.clone(), 2)
} else {
                            false
}
}
} else {
                    false
}
}
},
    _ => false,
}
}
}

pub fn peek_is_fat_arrow_at(tokens: Rc<Vec<Rc<Token>>>, state: Rc<ParserState>, offset: i64) -> bool {
    if ((state.pos.clone() + offset.clone()) < (tokens.clone().len() as i64)) {
        {
            let tok = tokens.clone().get(((state.pos.clone() + offset.clone())) as usize).cloned();
match tok.clone() {
    Some(t) => is_fat_arrow_shape(t.shape.clone()),
    None => false,
}
}
} else {
        false
}
}

pub fn peek_is_expected_at(tokens: Rc<Vec<Rc<Token>>>, state: Rc<ParserState>, offset: i64, expected: ExpectedToken) -> bool {
    if ((state.pos.clone() + offset.clone()) < (tokens.clone().len() as i64)) {
        {
            let tok = tokens.clone().get(((state.pos.clone() + offset.clone())) as usize).cloned();
match tok.clone() {
    Some(t) => shape_matches_expected(t.shape.clone(), expected.clone()),
    None => false,
}
}
} else {
        false
}
}

pub fn scan_for_fat_arrow_after_braces(tokens: Rc<Vec<Rc<Token>>>, state: Rc<ParserState>, start_offset: i64) -> bool {
    scan_braces_depth(tokens.clone(), state.clone(), (state.pos.clone() + start_offset.clone()), 1)
}

pub fn scan_braces_depth(mut tokens: Rc<Vec<Rc<Token>>>, mut state: Rc<ParserState>, mut idx: i64, mut depth: i64) -> bool {
    loop {
        if ((idx.clone() >= (tokens.clone().len() as i64)) || (depth.clone() <= 0)) {
            if (depth.clone() == 0) {
                if (idx.clone() < (tokens.clone().len() as i64)) {
                    let tok = tokens.clone().get((idx.clone()) as usize).cloned();
match tok.clone() {
    Some(t) => { break is_fat_arrow_shape(t.shape.clone()); },
    None => { break false; },
}
} else {
                    break false;
}
} else {
                break false;
}
} else {
            let tok = tokens.clone().get((idx.clone()) as usize).cloned();
match tok.clone() {
    Some(t) => { if is_lbrace_shape(t.shape.clone()) {
                {
                    let __tco_0 = tokens.clone();
let __tco_1 = state.clone();
let __tco_2 = (idx.clone() + 1);
let __tco_3 = (depth.clone() + 1);
tokens = __tco_0;
state = __tco_1;
idx = __tco_2;
depth = __tco_3;
continue;
}
} else {
                if is_rbrace_shape(t.shape.clone()) {
                    {
                        let __tco_0 = tokens.clone();
let __tco_1 = state.clone();
let __tco_2 = (idx.clone() + 1);
let __tco_3 = (depth.clone() - 1);
tokens = __tco_0;
state = __tco_1;
idx = __tco_2;
depth = __tco_3;
continue;
}
} else {
                    {
                        let __tco_0 = tokens.clone();
let __tco_1 = state.clone();
let __tco_2 = (idx.clone() + 1);
let __tco_3 = depth.clone();
tokens = __tco_0;
state = __tco_1;
idx = __tco_2;
depth = __tco_3;
continue;
}
}
} },
    None => { break false; },
}
}
}
}

