pub fn parse_string_interp(tokens: Rc<Vec<Rc<Token>>>, state: Rc<ParserState>) -> Rc<ExprResult> {
    {
        let span = current_span(tokens.clone(), state.clone());
let tok = peek(tokens.clone(), state.clone());
let sh = match tok.clone() {
    Some(t) => Some(t.shape.clone()),
    None => None,
};
match sh.clone() {
    Some(TokenShape::ShStrBegin) => {
            let prefix = tok.clone().unwrap().text.clone();
let adv = advance(tokens.clone(), state.clone());
let parts_init = if (v2_rt::string_length(prefix.clone()) > 0) {
                vec![Rc::new(StringPart::Text {
    value: prefix.clone(),
})]
} else {
                vec![]
};
parse_interp_parts(tokens.clone(), adv.state.clone(), parts_init.clone(), span.clone())
},
    _ => Rc::new(ExprResult {
    expr: parse_recovery_expr(span.clone(), "expected string interpolation".to_string()),
    state: state.clone(),
    err: Some(parse_error("expected string interpolation".to_string(), span.clone())),
}),
}
}
}

pub fn parse_interp_parts(mut tokens: Rc<Vec<Rc<Token>>>, mut state: Rc<ParserState>, mut parts: Vec<Rc<StringPart>>, mut span: Rc<SourceSpan>) -> Rc<ExprResult> {
    loop {
        let r = parse_expr(tokens.clone(), state.clone());
if has_err(r.err.clone()) {
            return r.clone()
}
let new_parts = v2_rt::list_push(parts.clone(), Rc::new(StringPart::Interpolation {
    expr: r.expr.clone(),
}));
let s = r.state.clone();
let interp_tok = peek(tokens.clone(), s.clone());
let interp_sh = match interp_tok.clone() {
    Some(t) => Some(t.shape.clone()),
    None => None,
};
match interp_sh.clone() {
    Some(TokenShape::ShStrMid) => { let mid = interp_tok.clone().unwrap().text.clone();
let adv = advance(tokens.clone(), s.clone());
let mid_parts = if (v2_rt::string_length(mid.clone()) > 0) {
            v2_rt::list_push(new_parts.clone(), Rc::new(StringPart::Text {
    value: mid.clone(),
}))
} else {
            new_parts.clone()
};
{
            let __tco_0 = tokens.clone();
let __tco_1 = adv.state.clone();
let __tco_2 = mid_parts.clone();
let __tco_3 = span.clone();
tokens = __tco_0;
state = __tco_1;
parts = __tco_2;
span = __tco_3;
continue;
} },
    Some(TokenShape::ShStrEnd) => { let suffix = interp_tok.clone().unwrap().text.clone();
let adv = advance(tokens.clone(), s.clone());
let final_parts = if (v2_rt::string_length(suffix.clone()) > 0) {
            v2_rt::list_push(new_parts.clone(), Rc::new(StringPart::Text {
    value: suffix.clone(),
}))
} else {
            new_parts.clone()
};
break Rc::new(ExprResult {
    expr: make_expr_node(Rc::new(ExprData::ExprStringInterp), { let mut __result = Vec::new(); for p in final_parts.clone().iter().cloned() { __result.push(match (*p.clone()).clone() {
    StringPart::Text { value: v, .. } => make_text_part_node(v.clone(), span.clone()),
    StringPart::Interpolation { expr: e, .. } => make_interp_part_node(e.clone(), span.clone()),
}); } __result }, None, span.clone()),
    state: adv.state.clone(),
    err: None,
}); },
    _ => { break Rc::new(ExprResult {
    expr: make_expr_node(Rc::new(ExprData::ExprStringInterp), { let mut __result = Vec::new(); for p in new_parts.clone().iter().cloned() { __result.push(match (*p.clone()).clone() {
    StringPart::Text { value: v, .. } => make_text_part_node(v.clone(), span.clone()),
    StringPart::Interpolation { expr: e, .. } => make_interp_part_node(e.clone(), span.clone()),
}); } __result }, None, span.clone()),
    state: s.clone(),
    err: None,
}); },
}
}
}

